("Đàm phán phức tạp", "Vòng đàm phán cuối của hợp đồng ba năm",
 [("provided that","/prəˈvaɪdɪd ðæt/","Liên từ","với điều kiện là","We'll sign provided that the price is fixed.","Chúng tôi sẽ ký với điều kiện giá cố định."),
  ("unless","/ənˈles/","Liên từ","trừ khi","Unless you agree, we can't proceed.","Trừ khi anh đồng ý, chúng ta không thể tiếp tục."),
  ("leverage","/ˈliːvərɪdʒ/","Danh từ","lợi thế, đòn bẩy","We have strong leverage.","Chúng ta có lợi thế lớn."),
  ("concession","/kənˈseʃn/","Danh từ","sự nhượng bộ","Both sides made concessions.","Hai bên đều nhượng bộ."),
  ("mutually","/ˈmjuːtʃuəli/","Trạng từ","đôi bên, lẫn nhau","A mutually beneficial deal.","Một thỏa thuận đôi bên cùng có lợi."),
  ("binding","/ˈbaɪndɪŋ/","Tính từ","có tính ràng buộc","The contract is legally binding.","Hợp đồng có tính ràng buộc pháp lý.")],
 ("Điều kiện nâng cao", "provided (that) / as long as + mệnh đề · unless = if not · Should you + V, ... (đảo ngữ điều kiện)", "Should you need anything, please call us = If you need anything, please call us.",
  [("We'll sign, ___ the price is fixed for two years.",["provided that","unless","despite","in case of"]),("___ you agree, we can't proceed.",["Unless","Provided","As long","If not"]),("___ you have any questions, please contact us.",["Should","Would","Could","Had"])]),
 [("Chúng tôi sẽ ký với điều kiện giá được giữ nguyên hai năm.","We will sign provided that the price is fixed for two years.","v"),("Unless both sides agree, the contract is not binding.","Trừ khi hai bên đồng ý, hợp đồng không có tính ràng buộc.","e"),("Chúng tôi sẵn sàng nhượng bộ về điều khoản thanh toán.","We are willing to make a concession on the payment terms.","v"),("Should you need more time, let us know.","Nếu anh cần thêm thời gian, hãy cho chúng tôi biết.","e")],
 ("a tough procurement director","Trưởng đoàn đàm phán","Vòng đàm phán cuối của hợp đồng ba năm.",["Đặt điều kiện bằng provided that","Đưa ra một nhượng bộ có đổi lại","Đạt thỏa thuận đôi bên cùng có lợi"],"Our final position: a 15% discount, or we walk away. What can you offer?")),

("Cụm từ cố định & sắc thái", "Trao đổi một quyết định khó với người hướng dẫn",
 [("draw a conclusion","/drɔː ə kənˈkluːʒn/","Cụm từ","rút ra kết luận","It's too early to draw a conclusion.","Còn quá sớm để rút ra kết luận."),
  ("raise a concern","/reɪz ə kənˈsɜːn/","Cụm từ","nêu mối lo ngại","She raised a concern about safety.","Cô ấy nêu mối lo ngại về an toàn."),
  ("meet a deadline","/miːt ə ˈdedlaɪn/","Cụm từ","kịp hạn chót","We met the deadline.","Chúng tôi đã kịp hạn."),
  ("take into account","/teɪk ˈɪntə əˈkaʊnt/","Cụm từ","tính đến","Take the costs into account.","Hãy tính đến chi phí."),
  ("bear in mind","/beər ɪn maɪnd/","Cụm từ","ghi nhớ, lưu ý","Bear in mind that it's risky.","Hãy lưu ý rằng nó rủi ro."),
  ("come to terms with","/kʌm tə tɜːmz wɪð/","Cụm từ","chấp nhận (điều khó)","He came to terms with the change.","Anh ấy đã chấp nhận sự thay đổi.")],
 ("Cụm từ cố định (collocations)", "make a decision · raise a concern · meet a deadline · bear in mind", "Người bản xứ nói 'make a decision', không nói 'do a decision'. Học theo cụm giúp nói tự nhiên hơn.",
  [("We need to ___ a decision today.",["make","do","take on","get"]),("She ___ a concern about the budget.",["raised","rose","lifted","arose"]),("Please ___ in mind that the office closes early.",["bear","keep on","hold","carry"])]),
 [("Chúng ta không nên vội rút ra kết luận.","We shouldn't jump to conclusions.","v"),("Please take the costs into account.","Hãy tính đến các chi phí.","e"),("Cô ấy đã nêu mối lo ngại về ngân sách.","She raised a concern about the budget.","v"),("It took him a while to come to terms with the change.","Anh ấy mất một thời gian mới chấp nhận được thay đổi.","e")],
 ("a mentor reviewing a difficult decision with you","Người học nâng cao","Bạn thảo luận một quyết định khó với người hướng dẫn.",["Dùng ít nhất 3 cụm từ cố định","Nêu một mối lo ngại","Rút ra kết luận"],"You said you had a difficult decision to make at work. Tell me about it.")),
